## 3. No input validation pattern established
**Severity: Medium**

### Issue
Current routes do not accept input, so there is no immediate exploit. But there is also no validation middleware or schema-based validation in place.

This is important because as soon as query params, route params, or body input are added, the app may become vulnerable to:
- injection
- unsafe type coercion
- prototype pollution via bad object handling
- malformed data causing errors

### Risk
Maps to:
- **OWASP A03 Injection**
- **A04 Insecure Design**
- **A05 Security Misconfiguration**

### Recommendation
Introduce validation now so future endpoints follow a safe pattern.

### Example using `express-validator`
```js
const { query, validationResult } = require('express-validator');

app.get(
  '/users',
  requireApiKey,
  query('limit').optional().isInt({ min: 1, max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ]);
  }
);
```

### Alternative with Joi
```js
const Joi = require('joi');

function validate(schema) {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.query, {
      abortEarly: false,
      stripUnknown: true,
    });

    if (error) {
      return res.status(400).json({
        error: 'Invalid request',
        details: error.details.map(d => d.message),
      });
    }

    req.query = value;
    next();
  };
}

const usersQuerySchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).optional(),
});

app.get('/users', requireApiKey, validate(usersQuerySchema), (req, res) => {
  res.json([{ id: 1, name: 'Alice' }]);
});
