- no role check,
- no least-privilege enforcement.

### Risk
An attacker or anonymous user can enumerate user information. This can support:
- phishing,
- account discovery,
- privacy violations,
- targeted attacks.

### Recommendation
Require authentication and authorization before returning user data.

### Example fix: simple API key middleware
```js
const express = require('express');
const app = express();

function requireApiKey(req, res, next) {
  const apiKey = req.get('x-api-key');
  if (!apiKey || apiKey !== process.env.API_KEY) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

app.get('/users', requireApiKey, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

### Better recommendation
Use a real auth mechanism:
- JWT validation,
- OAuth2/OIDC,
- session-based auth with secure cookies,
- role-based access control.

### Example role-based authorization pattern
```js
function requireAuth(req, res, next) {
  // Example only: populate req.user after token/session validation
  if (!req.user) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

function requireRole(role) {
  return (req, res, next) => {
    if (!req.user || !req.user.roles || !req.user.roles.includes(role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  };
}

app.get('/users', requireAuth, requireRole('admin'), (req, res) => {
  res.json([...]);
});
```

